function validate([n, edges, query]) {
  if (!Number.isInteger(n) || n < 1 || n > 1000) return 'n is between 1 and 1000.';
  if (!Array.isArray(edges) || edges.length !== n - 1) return 'edges must have exactly n - 1 pairs.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = v => { while (root[v] !== v) { root[v] = root[root[v]]; v = root[v]; } return v; };
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2 || edge.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Each edge is a pair of nodes between 0 and n - 1.';
    if (edge[0] === edge[1]) return 'An edge must join two different nodes.';
    const a = find(edge[0]), b = find(edge[1]);
    if (a === b) return 'The edges must form a tree (no cycles).';
    root[a] = b;
  }
  if (!Array.isArray(query) || query.length < 1 || query.length > 1000) return 'query has 1 to 1000 entries.';
  for (const q of query) {
    if (!Array.isArray(q) || q.length !== 3 || q.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Each query is [start, end, node] with nodes between 0 and n - 1.';
  }
  return null;
}

