function closestNode(n, edges, query) {
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
  // Depth-first search from one node, giving parent pointers and depths.
  const walk = from => {
    const parent = new Array(n).fill(-1), depth = new Array(n).fill(-1);
    const stack = [from];
    depth[from] = 0;
    while (stack.length) {
      const v = stack.pop();
      for (const w of adj[v]) if (depth[w] < 0) { depth[w] = depth[v] + 1; parent[w] = v; stack.push(w); }
    }
    return { parent, depth };
  };
  return query.map(([start, end, node]) => {
    // Climb from end to start along the parent pointers to list the path explicitly.
    const { parent } = walk(start);
    const path = [end];
    while (path[path.length - 1] !== start) path.push(parent[path[path.length - 1]]);
    const { depth } = walk(node);
    let best = path[0];
    for (const v of path) if (depth[v] < depth[best]) best = v;
    return best;
  });
}

