function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 1000 : 1 + pick(8);
  const m = size === 'large' ? 1000 : 1 + pick(5);
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = pick(i + 1); [label[i], label[j]] = [label[j], label[i]]; }
  // Node i hangs off one of the 'reach' nodes just before it: a small reach makes long paths, a large one bushy trees.
  const reach = size === 'large' ? [1, 3, n][pick(3)] : 1 + pick(n);
  const edges = [];
  for (let i = 1; i < n; i++) {
    const parent = i - 1 - pick(Math.min(reach, i));
    const edge = [label[i], label[parent]];
    edges.push(rand() < 0.5 ? edge : edge.reverse());
  }
  for (let i = edges.length - 1; i > 0; i--) { const j = pick(i + 1); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const query = Array.from({ length: m }, () => [label[pick(n)], label[pick(n)], label[pick(n)]]);
  return [n, edges, query];
}
